131	        this.householdId = householdId;
132	    }
133	
134	    public Integer getNamesakeCount() {
135	        return this.namesakeCount;
136	    }
137	
138	    public void setNamesakeCount(Integer namesakeCount) {
139	        this.namesakeCount = namesakeCount;
140	    }
141	
142	    /**
143	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
144	     */
145	    @Transient
146	    public String getDisplayName() {
147	        return this.getLastName() + ", " + this.getFirstName();
148	    }
149	
150	    /**
151	     * The owner's initials: the upper-cased first letters of the first and last name,
152	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
153	     */
154	    @Transient
155	    public String getInitials() {
156	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
157	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
158	    }
159	
160	    /**
161	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
162	     * the last two digits of the registration date year (e.g. {@code 'SMI-0007-M26'}). Derived from
163	     * the owner's own fields; {@code null} until both the customer code and registration date are set.
164	     */
165	    @Transient
166	    public String getMembershipNumber() {
167	        if (this.customerCode == null || this.registrationDate == null) {
168	            return null;
169	        }
170	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
171	    }
172	
173	    /**
174	     * The owner's numeric membership level, from 1 to 3. It starts at 1, gains 1 when the owner has
175	     * an email address, gains 1 when the owner is unique (namesakeCount is 0), and is capped at 3
176	     * (level 4 is reserved for tenure). The inputs are the owner's own fields.
177	     */
178	    @Transient
179	    public Integer getMembershipLevel() {
180	        int level = 1;
181	        boolean hasEmail = this.email != null && !this.email.isBlank();
182	        if (hasEmail) {
183	            level++;
184	        }
185	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
186	        if (unique) {
187	            level++;
188	        }
189	        return Math.min(level, 3);
190	    }
191	
192	    /**
193	     * The owner's locality: the canonical region derived from the city via the fixed city-to-region
194	     * table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code 'UNKNOWN'}
195	     * when the city is not in the table.
196	     */
197	    @Transient
198	    public String getLocality() {
199	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
200	    }
201	
202	    /**
203	     * The owner's identity key: a single derived value that consolidates all duplicate detection,
204	     * formatted {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. The
205	     * telephone is the stored E.164 value, the email its stored lower-cased form (empty when the
206	     * owner has none), and the household id the stored shared identifier (empty when the owner is
207	     * not part of a shared household). Two owners are duplicates only when their whole identity keys
208	     * are equal; because the telephone is part of the key, two members of the same household with
209	     * different telephones have different identity keys.
210	     */
211	    @Transient
212	    public String getIdentityKey() {
213	        String telephonePart = this.telephone == null ? "" : this.telephone;
214	        String emailPart = this.email == null ? "" : this.email;
215	        String householdPart = this.householdId == null ? "" : this.householdId;
216	        return telephonePart + "|" + emailPart + "|" + householdPart;
217	    }
218	
219	    /**
220	     * The owner's preferred contact channel, derived from the owner's own fields:
221	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
222	     */
223	    @Transient
224	    public String getContactPreference() {
225	        boolean hasEmail = this.email != null && !this.email.isBlank();
226	        return hasEmail ? "EMAIL" : "PHONE";
227	    }
228	
229	    protected Set<Pet> getPetsInternal() {
230	        if (this.pets == null) {
231	            this.pets = new HashSet<>();
232	        }
233	        return this.pets;
234	    }
235	
236	    protected void setPetsInternal(Set<Pet> pets) {
237	        this.pets = pets;
238	    }
239	
240	    public List<Pet> getPets() {
241	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
242	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
243	        return Collections.unmodifiableList(sortedPets);
244	    }
245	
246	    public void setPets(List<Pet> pets) {
247	        this.pets = new HashSet<>(pets);
248	    }
249	
250	    public void addPet(Pet pet) {
251	        getPetsInternal().add(pet);
252	        pet.setOwner(this);
253	    }
254	
255	    /**
256	     * Return the Pet with the given name, or null if none found for this Owner.
257	     *
258	     * @param name to test
259	     * @return true if pet name is already in use
260	     */
261	    public Pet getPet(String name) {
262	        return getPet(name, false);
263	    }
264	
265	    /**
266	     * Return the Pet with the given name, or null if none found for this Owner.
267	     *
268	     * @param name to test
269	     * @return true if pet name is already in use
270	     */
271	    public Pet getPet(String name, boolean ignoreNew) {
272	        name = name.toLowerCase();
273	        for (Pet pet : getPetsInternal()) {
274	            if (!ignoreNew || !pet.isNew()) {
275	                String compName = pet.getName();
276	                compName = compName.toLowerCase();
277	                if (compName.equals(name)) {
278	                    return pet;
279	                }
280	            }
281	        }
282	        return null;
283	    }
284	
285	    public Pet getPet(Integer petId) {
286	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
287	    }
288	
289	    @Override
290	    public String toString() {
291	        return new ToStringCreator(this)
292	
293	            .append("id", this.getId())
294	            .append("new", this.isNew())
295	            .append("lastName", this.getLastName())
296	            .append("firstName", this.getFirstName())
297	            .append("address", this.address)
298	            .append("city", this.city)
299	            .append("telephone", this.telephone)
300	            .toString();
301	    }
302	}
