65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
74	     * domain containing at least one dot, with no whitespace in any part.
75	     */
76	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
77	
78	    /**
79	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
80	     * new owner's id, customer code and registration date.
81	     */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    /**
85	     * Common street-type abbreviations expanded during address normalization. Keys are the
86	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
87	     * expanded form it is replaced with.
88	     */
89	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
90	        "ST", "STREET",
91	        "RD", "ROAD",
92	        "AVE", "AVENUE");
93	
94	    /**
95	     * The maximum number of owners a single city may contain. Once a city holds this many owners it
96	     * is at capacity and cannot take any more.
97	     */
98	    private static final int CITY_CAPACITY = 50;
99	
100	    /**
101	     * The maximum number of owners that may be registered in a single day. Once this many owners
102	     * already carry today's {@code registrationDate}, the day's quota is exhausted and no further
103	     * owners can be created that day.
104	     */
105	    private static final int DAILY_OWNER_LIMIT = 100;
106	
107	    /**
108	     * The number of owners that may be registered on a single business day before a response starts
109	     * carrying a {@code bulkSignupWarning}. Once <em>more than</em> this many owners already carry the
110	     * current business day's {@code registrationDate}, that day's signups are flagged as unusually
111	     * high volume.
112	     */
113	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
114	
115	    /**
116	     * E.164 country codes mapped to the exact number of national (significant) digits a telephone for
117	     * that country must carry. For example {@code '+61'} (Australia) requires 9 national digits and
118	     * {@code '+1'} (NANP) requires 10. A country code listed here enforces that national-number length;
119	     * a number whose country code is not listed is accepted at any otherwise-valid E.164 length.
120	     */
121	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
122	        "61", 9,
123	        "1", 10);
124	
125	    private final ClinicService clinicService;
126	
127	    private final OwnerMapper ownerMapper;
128	
129	    private final PetMapper petMapper;
130	
131	    private final VisitMapper visitMapper;
132	
133	    public OwnerRestControllerV1(ClinicService clinicService,
134	                                 OwnerMapper ownerMapper,
135	                                 PetMapper petMapper,
136	                                 VisitMapper visitMapper) {
137	        this.clinicService = clinicService;
138	        this.ownerMapper = ownerMapper;
139	        this.petMapper = petMapper;
140	        this.visitMapper = visitMapper;
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
146	        Collection<Owner> owners;
147	        if (lastName != null) {
148	            owners = this.clinicService.findOwnerByLastName(lastName);
149	        } else {
150	            owners = this.clinicService.findAllOwners();
151	        }
152	        if (owners.isEmpty()) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
166	        applyBulkSignupWarning(ownerDto);
167	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
173	        validateRequiredFields(ownerFieldsDto);
174	        LocalDate registrationDate = toBusinessDay(
175	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
176	        rejectDailyLimitReached(registrationDate);
177	        HttpHeaders headers = new HttpHeaders();
178	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
179	        String address = normalizeAddress(ownerFieldsDto.getAddress());
180	        owner.setAddress(address);
181	        rejectCityAtCapacity(owner.getCity());
182	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
183	            assignHousehold(owner, ownerFieldsDto.getLastName(), address);
184	        }
185	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
186	        owner.setTelephone(telephone);
187	        String email = normalizeEmail(ownerFieldsDto.getEmail());
188	        owner.setEmail(email);
189	        rejectDuplicateIdentity(owner);
190	        owner.setRegistrationDate(registrationDate);
191	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
192	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
193	        this.clinicService.saveOwner(owner);
194	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
195	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
196	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
197	        applyBulkSignupWarning(ownerDto);
198	        headers.setLocation(UriComponentsBuilder.newInstance()
199	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
200	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
206	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
207	        if (currentOwner == null) {
208	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	        }
210	        currentOwner.setAddress(ownerFieldsDto.getAddress());
211	        currentOwner.setCity(ownerFieldsDto.getCity());
212	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
213	        currentOwner.setLastName(ownerFieldsDto.getLastName());
214	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
215	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
216	        this.clinicService.saveOwner(currentOwner);
217	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Transactional
222	    @Override
223	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
224	        Owner owner = this.clinicService.findOwnerById(ownerId);
225	        if (owner == null) {
226	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	        }
228	        this.clinicService.deleteOwner(owner);
229	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
230	    }
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
233	    @Override
234	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
235	        Owner owner = this.clinicService.findOwnerById(ownerId);
236	        if (owner == null) {
237	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
238	        }
239	        HttpHeaders headers = new HttpHeaders();
240	        Pet pet = petMapper.toPet(petFieldsDto);
241	        owner.setId(ownerId);
242	        pet.setOwner(owner);
243	        pet.getType().setName(null);
244	        this.clinicService.savePet(pet);
245	        PetDto petDto = petMapper.toPetDto(pet);
246	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
247	            .buildAndExpand(pet.getId()).toUri());
248	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
249	    }
250	
251	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
252	    @Override
253	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
254	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
255	        if (currentOwner != null) {
256	            Pet currentPet = this.clinicService.findPetById(petId);
257	            if (currentPet != null) {
258	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
259	                currentPet.setName(petFieldsDto.getName());
260	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
261	                this.clinicService.savePet(currentPet);
262	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
263	            }
264	        }
265	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
266	    }
267	
268	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
269	    @Override
270	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
271	        HttpHeaders headers = new HttpHeaders();
272	        Visit visit = visitMapper.toVisit(visitFieldsDto);
273	        Pet pet = new Pet();
274	        pet.setId(petId);
275	        visit.setPet(pet);
276	        this.clinicService.saveVisit(visit);
277	        VisitDto visitDto = visitMapper.toVisitDto(visit);
278	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
279	            .buildAndExpand(visit.getId()).toUri());
280	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
281	    }
282	
283	
284	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
285	    @Override
286	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
287	        Owner owner = this.clinicService.findOwnerById(ownerId);
288	        if (owner != null) {
289	            Pet pet = owner.getPet(petId);
290	            if (pet != null) {
291	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
292	            }
293	        }
294	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
295	    }
296	
297	    /**
298	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
299	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
300	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
301	     *
302	     * @param ownerFieldsDto the submitted owner fields
303	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
304	     *                                     name of every offending field
305	     */
306	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
307	        List<String> missingFields = new ArrayList<>();
308	        if (isBlank(ownerFieldsDto.getFirstName())) {
309	            missingFields.add("firstName");
310	        }
311	        if (isBlank(ownerFieldsDto.getLastName())) {
312	            missingFields.add("lastName");
313	        }
314	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
315	            missingFields.add("address");
316	        }
317	        if (isBlank(ownerFieldsDto.getCity())) {
318	            missingFields.add("city");
319	        }
320	        if (isBlank(ownerFieldsDto.getTelephone())) {
321	            missingFields.add("telephone");
322	        }
323	        if (!missingFields.isEmpty()) {
324	            throw new InvalidOwnerFieldsException(missingFields);
325	        }
326	    }
327	
328	    private boolean isBlank(String value) {
329	        return value == null || value.isBlank();
330	    }
331	
332	    /**
333	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
334	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
335	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
336	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
337	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
338	     *
339	     * @param telephone the raw telephone value submitted by the client
340	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
341	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
342	     *                                     400 response
343	     */
344	    private String normalizeTelephone(String telephone) {
345	        String e164 = toE164(telephone);
346	        if (e164 == null) {
347	            throw new InvalidOwnerFieldsException(List.of("telephone"));
348	        }
349	        return e164;
350	    }
351	
352	    /**
353	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
354	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
355	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
356	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
357	     * and when the supplied country code is one with a known national-number length
358	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
359	     * number must have exactly that many digits.
360	     *
361	     * @param telephone the raw telephone value, possibly {@code null}
362	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
363	     */
364	    private String toE164(String telephone) {
365	        if (telephone == null) {
366	            return null;
367	        }
368	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
369	        boolean hasPlus = cleaned.startsWith("+");
370	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
371	        String nationalSignificant = hasPlus
372	            ? digits
373	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
374	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
375	            return null;
376	        }
377	        if (!hasValidNationalNumberLength(nationalSignificant)) {
378	            return null;
379	        }
380	        return "+" + nationalSignificant;
381	    }
382	
383	    /**
384	     * Checks the national-number length of an E.164 number (country code plus national significant
385	     * digits, no leading {@code '+'}) against the per-country requirement in
386	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
387	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
388	     * country code is not listed carries no per-country length requirement and is accepted.
389	     *
390	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
391	     *                            leading {@code '+'}
392	     * @return {@code true} if the national-number length is correct for the country code, or the
393	     *         country code has no listed requirement; {@code false} otherwise
394	     */
395	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
396	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
397	            .filter(nationalSignificant::startsWith)
398	            .max(Comparator.comparingInt(String::length))
399	            .orElse(null);
400	        if (countryCode == null) {
401	            return true;
402	        }
403	        int nationalLength = nationalSignificant.length() - countryCode.length();
404	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
405	    }
406	
407	    /**
408	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
409	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
410	     * returned value is that address lower-cased.
411	     *
412	     * @param email the raw email value submitted by the client, or {@code null} if omitted
413	     * @return the lower-cased email, or {@code null} if none was supplied
414	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
415	     *                                     yielding a 400 response
416	     */
417	    private String normalizeEmail(String email) {
418	        if (email == null) {
419	            return null;
420	        }
421	        if (!EMAIL_PATTERN.matcher(email).matches()) {
422	            throw new InvalidOwnerFieldsException(List.of("email"));
423	        }
424	        return email.toLowerCase(Locale.ROOT);
425	    }
426	
427	    /**
428	     * Counts the existing owners that, before this create, already share the given first name and
429	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
430	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
431	     * been saved yet, so it is never included in the count.
432	     *
433	     * @param firstName the first name of the owner being created
434	     * @param lastName  the last name of the owner being created
435	     * @return the number of existing owners sharing both names
436	     */
437	    private int countNamesakes(String firstName, String lastName) {
438	        String normalizedFirstName = normalizeForComparison(firstName);
439	        String normalizedLastName = normalizeForComparison(lastName);
440	        return (int) this.clinicService.findAllOwners().stream()
441	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
442	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
443	            .count();
444	    }
445	
446	    /**
447	     * Builds the owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3}
448	     * is the upper-cased first three letters of the city, {@code LAST3} the upper-cased first three
449	     * letters of the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one
450	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
451	     *
452	     * @param city     the owner's city
453	     * @param lastName the owner's last name
454	     * @return the formatted customer code
455	     */
456	    private String generateCustomerCode(String city, String lastName) {
457	        String city3 = first3Letters(city);
458	        String last3 = first3Letters(lastName);
459	        int sequence = countOwnersInCity(city) + 1;
460	        return String.format("%s-%s-%04d", city3, last3, sequence);
461	    }
462	
463	    /**
464	     * Returns the upper-cased first three letters of the given value, with any non-letter characters
465	     * removed first, used to build the city and last-name segments of a {@code customerCode}.
466	     *
467	     * @param value the value to abbreviate
468	     * @return the upper-cased first three letters, or fewer if the value has fewer letters
469	     */
470	    private String first3Letters(String value) {
471	        String letters = value.replaceAll("[^\\p{L}]", "");
472	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
473	    }
474	
475	    /**
476	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
477	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
478	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
479	     * has not been saved yet, so it is never included in the count.
480	     *
481	     * @param city the city of the owner being created
482	     * @return the number of existing owners in that city
483	     */
484	    private int countOwnersInCity(String city) {
485	        String normalizedCity = normalizeForComparison(city);
486	        return (int) this.clinicService.findAllOwners().stream()
487	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
488	            .count();
489	    }
490	
491	    /**
492	     * Rejects creation of an owner whose city already contains the maximum number of owners
493	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
494	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
495	     *
496	     * @param city the city of the owner being created
497	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
498	     *                                      owners, yielding a 409 Conflict response
499	     */
500	    private void rejectCityAtCapacity(String city) {
501	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
502	            throw new OwnerCityAtCapacityException(city);
503	        }
504	    }
505	
506	    /**
507	     * Rejects creation of an owner once the given business day has already reached its daily quota
508	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
509	     * being that day — the adjusted business day the owner being created will carry — so the quota
510	     * applies per business day. The owner being created has not been saved yet, so it is never
511	     * included in the count.
512	     *
513	     * @param registrationDate the adjusted business-day registration date of the owner being created
514	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
515	     *                                         carry that registration date, yielding a
516	     *                                         429 Too Many Requests response
517	     */
518	    private void rejectDailyLimitReached(LocalDate registrationDate) {
519	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
520	            throw new DailyOwnerLimitReachedException(registrationDate);
521	        }
522	    }
523	
524	    /**
525	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
526	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
527	     *
528	     * @param registrationDate the business day to count owners for
529	     * @return the number of existing owners registered on that day
530	     */
531	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
532	        return this.clinicService.findAllOwners().stream()
533	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
534	            .count();
535	    }
536	
537	    /**
538	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
539	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
540	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
541	     * otherwise.
542	     *
543	     * @param ownerDto the owner response to flag
544	     */
545	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
546	        LocalDate today = toBusinessDay(LocalDate.now());
547	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
548	    }
549	
550	    /**
551	     * Rolls a registration date forward to a business day. A date that falls on a Saturday or Sunday
552	     * is rolled forward to the next Monday; a date already on a weekday is returned unchanged. This
553	     * applies to the effective registration date whether it was supplied in the request or defaulted
554	     * to the server date, and the adjusted value is what gets stored as {@code registrationDate} and
555	     * feeds every value derived from it (such as the membership number's year segment and the daily
556	     * create-limit's per-day bucket).
557	     *
558	     * @param date the effective registration date, supplied or defaulted
559	     * @return the same date when it is a weekday, otherwise the next Monday
560	     */
561	    private LocalDate toBusinessDay(LocalDate date) {
562	        LocalDate adjusted = date;
563	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
564	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
565	            adjusted = adjusted.plusDays(1);
566	        }
567	        return adjusted;
568	    }
569	
570	    /**
571	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
572	     * owner's. The identity key — {@code '<normalizedTelephone>|<email or empty>|<householdId or
573	     * empty>'} — is the single value that consolidates all duplicate detection: the previously
574	     * separate telephone, email and household checks are all expressed through it. Because the
575	     * telephone is part of the key, two members of the same household (same {@code householdId})
576	     * with different telephones have different identity keys and are both allowed; only a whole-key
577	     * match is a duplicate. The owner being created already carries its normalized telephone,
578	     * email and (if any) household id, and existing owners store the same normalized forms, so the
579	     * keys are compared directly.
580	     *
581	     * @param owner the owner being created, with its telephone, email and household id already set
582	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
583	     *                                         yielding a 409 Conflict response
584	     */
585	    private void rejectDuplicateIdentity(Owner owner) {
586	        String identityKey = owner.getIdentityKey();
587	        boolean inUse = this.clinicService.findAllOwners().stream()
588	            .map(Owner::getIdentityKey)
589	            .anyMatch(identityKey::equals);
590	        if (inUse) {
591	            throw new DuplicateOwnerIdentityException(identityKey);
592	        }
593	    }
594	
595	    /**
596	     * Finds every existing owner belonging to the household identified by the given last name and
597	     * address — that is, the owners the {@code sharesHousehold} opt-in joins. Both the last name and
598	     * the address are compared case-insensitively with surrounding and internal whitespace collapsed,
599	     * so values that differ only in letter case or spacing still match. This definition of household
600	     * membership is used by {@link #assignHousehold}.
601	     *
602	     * @param lastName the last name of the owner being created
603	     * @param address  the address of the owner being created
604	     * @return the existing owners in that household, or an empty list if there are none
605	     */
606	    private List<Owner> findHouseholdMembers(String lastName, String address) {
607	        String normalizedLastName = normalizeForComparison(lastName);
608	        String normalizedAddress = normalizeAddress(address);
609	        return this.clinicService.findAllOwners().stream()
610	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
611	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
612	            .toList();
613	    }
614	
615	    /**
616	     * Enrolls a newly created owner into the household of any existing owner that shares its last
617	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
618	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
619	     * whitespace. When at least one such owner already exists, every member of the household — the
620	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
621	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
622	     * and address is created and back-filled onto the existing members. When no owner yet lives at
623	     * that address under the same last name no identifier is assigned and the owner is created alone.
624	     *
625	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
626	     * @param lastName the last name of the owner being created
627	     * @param address  the address of the owner being created
628	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
629	     */
630	    private String assignHousehold(Owner newOwner, String lastName, String address) {
631	        List<Owner> members = findHouseholdMembers(lastName, address);
632	        if (members.isEmpty()) {
633	            return null;
634	        }
635	        String householdId = members.stream()
636	            .map(Owner::getHouseholdId)
637	            .filter(existing -> existing != null && !existing.isBlank())
638	            .findFirst()
639	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
640	        for (Owner member : members) {
641	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
642	                member.setHouseholdId(householdId);
643	                this.clinicService.saveOwner(member);
644	            }
645	        }
646	        newOwner.setHouseholdId(householdId);
647	        return householdId;
648	    }
649	
650	    /**
651	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
652	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
653	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
654	     * same identifier, so members of one household share a single value.
655	     *
656	     * @param normalizedLastName the household's last name, already normalized for comparison
657	     * @param normalizedAddress  the household's address, already normalized for comparison
658	     * @return the derived household identifier
659	     */
660	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
661	        try {
662	            byte[] digest = MessageDigest.getInstance("SHA-256")
663	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
664	            StringBuilder hex = new StringBuilder(digest.length * 2);
665	            for (byte b : digest) {
666	                hex.append(String.format("%02x", b));
667	            }
668	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
669	        } catch (NoSuchAlgorithmException e) {
670	            throw new IllegalStateException("SHA-256 algorithm not available", e);
671	        }
672	    }
673	
674	    /**
675	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
676	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
677	     * the result is lower-cased.
678	     *
679	     * @param value the value to normalize, possibly {@code null}
680	     * @return the normalized value, or an empty string if {@code value} is {@code null}
681	     */
682	    private String normalizeForComparison(String value) {
683	        if (value == null) {
684	            return "";
685	        }
686	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
687	    }
688	
689	    /**
690	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
691	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
692	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
693	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
694	     * This normalized value is what gets stored and returned, and it is the form every address
695	     * comparison (household duplicate detection and the shared household id) uses.
696	     *
697	     * @param address the raw address value submitted by the client, possibly {@code null}
698	     * @return the normalized address, or an empty string if {@code address} is {@code null}
699	     */
700	    private String normalizeAddress(String address) {
701	        if (address == null) {
702	            return "";
703	        }
704	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
705	        if (collapsed.isEmpty()) {
706	            return collapsed;
707	        }
708	        String[] tokens = collapsed.split(" ");
709	        StringBuilder normalized = new StringBuilder(collapsed.length());
710	        for (int i = 0; i < tokens.length; i++) {
711	            if (i > 0) {
712	                normalized.append(' ');
713	            }
714	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
715	        }
716	        return normalized.toString();
717	    }
718	}
