17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the given identity key already exists";
57	    private static final String ERROR_CITY_AT_CAPACITY = "The given city already contains the maximum number of owners";
58	    private static final String ERROR_DAILY_LIMIT_REACHED = "The maximum number of owners has already been created today";
59	
60	    /**
61	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
62	     * class.
63	     *
64	     * @param e     Object referring to the thrown exception.
65	     * @param status HTTP response status.
66	     * @param url URL request.
67	     */
68	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
69	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
70	        problemDetail.setType(URI.create(url.toString()));
71	        problemDetail.setTitle(e.getClass().getSimpleName());
72	        problemDetail.setDetail(detail);
73	        problemDetail.setProperty("timestamp", Instant.now());
74	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
75	        return problemDetail;
76	    }
77	
78	    /**
79	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
80	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
81	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
82	     * would catch it and report an authorization failure as a 500.
83	     *
84	     * @param e The {@link AccessDeniedException} to propagate
85	     * @throws AccessDeniedException always
86	     */
87	    @ExceptionHandler(AccessDeniedException.class)
88	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
89	        throw e;
90	    }
91	
92	    /**
93	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
94	     *
95	     * @param e The {@link Exception} to be handled
96	     * @param request {@link HttpServletRequest} object referring to the current request.
97	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
98	     */
99	    @ExceptionHandler(Exception.class)
100	    @ResponseBody
101	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
102	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
103	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
104	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
105	        return ResponseEntity.status(status).body(detail);
106	    }
107	
108	    /**
109	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
110	     * method returns a 404 Not Found status if an entity does not exist.
111	     *
112	     * @param e The {@link DataIntegrityViolationException} to be handled
113	     * @param request {@link HttpServletRequest} object referring to the current request.
114	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
115	     */
116	    @ExceptionHandler(DataIntegrityViolationException.class)
117	    @ResponseBody
118	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
119	        logger.warn("Data integrity violation at {} {}: {}",
120	            request.getMethod(),
121	            request.getRequestURI(),
122	            e.getMessage());
123	        logger.debug("Data integrity violation stacktrace", e);
124	        HttpStatus status = HttpStatus.NOT_FOUND;
125	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
126	        return ResponseEntity.status(status).body(detail);
127	    }
128	
129	    /**
130	     * Handles exception thrown by Bean Validation on controller methods parameters
131	     *
132	     * @param e The {@link MethodArgumentNotValidException} to be handled
133	     * @param request {@link HttpServletRequest} object referring to the current request.
134	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
135	     */
136	    @ExceptionHandler(MethodArgumentNotValidException.class)
137	    @ResponseBody
138	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
139	        HttpStatus status = HttpStatus.BAD_REQUEST;
140	        BindingErrorsResponse errors = new BindingErrorsResponse();
141	        BindingResult bindingResult = e.getBindingResult();
142	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
143	        if (bindingResult.hasErrors()) {
144	            errors.addAllErrors(bindingResult);
145	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
146	                .map(fieldError -> {
147	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
148	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
149	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
150	                        fieldError.getField(),
151	                        defaultMessage,
152	                        rejectedValue);
153	                    return new ValidationMessageDto(message)
154	                        .putAdditionalProperty("field", fieldError.getField())
155	                        .putAdditionalProperty("rejectedValue", rejectedValue)
156	                        .putAdditionalProperty("defaultMessage", defaultMessage);
157	                })
158	                .toList();
159	            logger.debug("Validation error at {} {}: {}",
160	                request.getMethod(),
161	                request.getRequestURI(),
162	                bindingResult.getFieldErrors());
163	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
164	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
165	                .map(FieldError::getField)
166	                .distinct()
167	                .toList();
168	            detail.setProperty("errors", invalidFields);
169	            return ResponseEntity.status(status).body(detail);
170	        }
